 mountReliability(root,rerender,id=>{flowEvent=id==='kds'?'service':id==='normal'||id==='printer'||id==='payment'||id==='offline'?'sale':flowEvent;});const observer=new ResizeObserver(draw);observer.observe(canvas);function choose(id){selected=id;rerender();}root.querySelectorAll('[data-equipment]').forEach(button=>button.addEventListener('click',()=>choose(button.dataset.equipment)));root.querySelector('#equipment-zone').addEventListener('change',e=>{zone=e.target.value;if(zone!=='all'&&allNodes().find(d=>d.id===selected).zone!=='system'&&allNodes().find(d=>d.id===selected).zone!==zone)selected=EQUIPMENT.find(d=>d.zone===zone).id;rerender();});root.querySelector('#equipment-yaw').addEventListener('input',e=>{yaw=Number(e.target.value)*Math.PI/180;draw();});root.querySelector('#equipment-zoom').addEventListener('input',e=>{zoom=Number(e.target.value)/100;draw();});root.querySelector('#equipment-links').addEventListener('change',e=>{showLinks=e.target.checked;draw();});root.querySelector('#equipment-reset').addEventListener('click',()=>{yaw=-.55;pitch=.65;zoom=1;rerender();});
 canvas.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY,yaw,pitch};dragged=false;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.abs(dx)+Math.abs(dy)>4)dragged=true;yaw=down.yaw+dx*.008;pitch=Math.max(.25,Math.min(1.15,down.pitch+dy*.005));root.querySelector('#equipment-yaw').value=((yaw*180/Math.PI+180)%360+360)%360-180;draw();});canvas.addEventListener('pointerup',e=>{if(!down)return;if(!dragged){const box=canvas.getBoundingClientRect(),x=e.clientX-box.left,y=e.clientY-box.top,target=hit.find(p=>x>=p.minX&&x<=p.maxX&&y>=p.minY&&y<=p.maxY);if(target)choose(target.id);}down=null;});canvas.addEventListener('pointercancel',()=>{down=null;});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.4,zoom-e.deltaY*.001));root.querySelector('#equipment-zoom').value=zoom*100;draw();},{passive:false});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')yaw-=.12;if(e.key==='ArrowRight')yaw+=.12;if(e.key==='ArrowUp')pitch=Math.min(1.15,pitch+.08);if(e.key==='ArrowDown')pitch=Math.max(.25,pitch-.08);draw();}});root.querySelector('#equipment-event').addEventListener('change',e=>{flowEvent=e.target.value;flowClock=0;rerender();});root.querySelector('#equipment-play').addEventListener('click',()=>{flowPlaying=!flowPlaying;rerender();});root.querySelector('#equipment-speed').addEventListener('click',()=>{flowSpeed=flowSpeed===1?2:flowSpeed===2?.5:1;rerender();});function tick(now){if(flowPlaying&&!document.hidden){if(last)flowClock+=Math.min((now-last)/1000,.1)*flowSpeed;if(now-lastDraw>=33){draw();lastDraw=now;}}last=now;raf=requestAnimationFrame(tick);}draw();raf=requestAnimationFrame(tick);cleanup=()=>{observer.disconnect();cancelAnimationFrame(raf);};
